        itemCycleCountOverviewTable.ToDateTime   = utcDateTimeNull();
        itemCycleCountOverviewTable.selectForUpdate(true);
        ttsbegin;
        itemCycleCountOverviewTable.update();
        ttscommit;

        sysOperationStartResult = super();
        if (args && args.caller())
        {
            FormRun     formRun = args.caller();
            FormDataSource itemCycleCountOverviewTableDS =  formRun.dataSource(formDataSourceStr(AVAItemCycleCountOverview,AVAItemCycleCountOverviewTable));
            itemCycleCountOverviewTableDS.query().dataSourceTable(tableNum(AVAItemCycleCountOverviewTable)).addRange(fieldNum(AVAItemCycleCountOverviewTable,InventLocationId)).value(inventLocationId);
            itemCycleCountOverviewTableDS.executeQuery();
